DELETE FROM SYS_RBAC_ROLE_RELATE T
WHERE T.ROLE_CODE = #{roleCode}
AND (
  (T.r_type = #{moduleRType}


        AND T.R_CODE1 NOT IN

            #{moduleCode}


    AND EXISTS (SELECT 1
        FROM SYS_RBAC_MENU_MODULE t1
        WHERE t1.bus_type = #{busCode}
        AND t1.r_id = T.R_CODE1)
    )
  OR
  (T.r_type = #{pageRType}


        AND
        T.R_CODE1 NOT IN

            #{pageCode}


    AND EXISTS (SELECT 1
            FROM SYS_RBAC_MENU_PAGE t1
            WHERE t1.bus_type = #{busCode}
            AND t1.r_id = T.R_CODE1)
    )
)

DELETE FROM SYS_RBAC_ROLE_RELATE T
